record.field:
if self.estimated_cost > 100000:
   if len(self.tor_committee_ids) < 1:
        failed = True

if self.estimated_cost > 100000:
   if len(self.price_determine_committee_ids) < 1:
        failed = True

if self.estimated_cost > 500000:
   if len(self.evaluation_committee_ids) < 1:
        failed = True

ALLOWED = {"tor_committee", "evaluation", "work_supervisor"}
buckets = (
    self.procurement_committee_ids
    | self.work_acceptance_committee_ids
    | self.tor_committee_ids
    | self.price_determine_committee_ids
    | self.evaluation_committee_ids
    | self.work_supervisor_ids
)
by_emp = {}
for line in buckets:
    if line.employee_id:
        by_emp.setdefault(line.employee_id.id, set()).add(line.committee_type)
for types in by_emp.values():
    if len(types) > 1 and not types.issubset(ALLOWED):
        failed = True
        break
